-- name: RegisterDevice :exec
INSERT INTO notifications_devices (
	id,
	scope,
	principal,
	platform,
	token,
	last_seen_at
) VALUES (
	sqlc.arg(id),
	sqlc.arg(scope),
	sqlc.arg(principal),
	sqlc.arg(platform),
	sqlc.arg(token),
	sqlc.arg(last_seen_at)
)
ON CONFLICT (platform, token) DO UPDATE SET
	scope = EXCLUDED.scope,
	principal = EXCLUDED.principal,
	last_seen_at = EXCLUDED.last_seen_at;

